from baseline_registry import ROOT,REPO,ref,dump
V=ROOT/'validation/integrated';out=V/sys.argv[1];out.mkdir();shutil.copyfile(__file__,out/'producer.py');rows=[]
for n in sys.argv[2:]:
 src=V/n;s=json.loads((src/'summary.json').read_text());a=np.load(src/'field.npz');p=a['points_mm'];t=a['tetra'];u=a['displacement_mm'];X=p[t[:,1:]]-p[t[:,0,None]];iv=np.linalg.inv(X);vol=abs(np.linalg.det(X))/6;grad=np.zeros((len(t),4,3));grad[:,1:]=iv.transpose(0,2,1);grad[:,0]=-grad[:,1:].sum(1);G=np.einsum('tai,taj->tij',u[t],grad);eps=(G+G.transpose(0,2,1))/2;E=s['E_ASSUMED_MPa'];nu=s['nu_ASSUMED'];mu=E/(2*(1+nu));la=E*nu/((1+nu)*(1-2*nu));sig=2*mu*eps+la*np.trace(eps,axis1=1,axis2=2)[:,None,None]*np.eye(3);dev=sig-np.trace(sig,axis1=1,axis2=2)[:,None,None]*np.eye(3)/3;vm=np.sqrt(1.5*np.sum(dev**2,axis=(1,2)));ratio=np.linalg.det(np.eye(3)[None]+G);eigen=np.linalg.eigvalsh(eps);energy=float(np.sum(.5*np.einsum('tij,tij->t',eps,sig)*vol));rows.append(dict(source=ref(src/'summary.json'),field=ref(src/'field.npz'),full_surface_and_contact_reference=all(s['checks'].values()) and s['accepted_load_fraction']==1.,raw_maximum_vm_MPa=float(vm.max()),raw_maximum_absolute_principal_strain=float(abs(eigen).max()),minimum_deformed_volume_ratio=float(ratio.min()),maximum_displacement_mm=float(np.linalg.norm(u,axis=1).max()),element_energy_Nmm=energy,energy_relative_error=abs(energy/s['static_energy_Nmm']-1),positive_elements=bool(ratio.min()>0),minimum_supported_strength_MPa=None,strength_safety_factor=None,capacity_qualified=False))
checks=dict(nonempty=bool(rows),all_positive_deformed_elements=all(q['positive_elements'] for q in rows),all_independent_element_energy=all(q['energy_relative_error']<1e-8 for q in rows))
dump(out/'summary.json',dict(status='ACTUAL_P1_PLATE_RAW_STRESS_STRAIN_AND_DEFORMED_VOLUME_NOT_CAPACITY',candidate=s['candidate'],producer=ref(out/'producer.py'),checks=checks,rows=rows,newly_qualified_system_gate_ids=[],whole_system_release=False,limitations=['Actual wholefooted plate tetra fields; raw stresses/strains not minimumstrength/capacity or notch convergence. Assumed E/nu/rho/mu unchanged. Failedcontact field remains failed despite positive elements. No nullstrength replacedbyzero.']))
